<?php
$root=$argv[1];$url=getenv('FIXTURE_URL');$_SERVER['HTTP_HOST']=parse_url($url,PHP_URL_HOST).':'.parse_url($url,PHP_URL_PORT);require $root.'/wp-load.php';wp_set_current_user(1);
$existing=get_option('cloner_fixture_autoplay_page');if($existing&&get_post($existing)&&get_option('cloner_fixture_autoplay_ready')){echo json_encode(['url'=>get_permalink($existing),'existing'=>true])."\n";exit;}
$context=\Nextend\SmartSlider3\Application\ApplicationSmartSlider3::getInstance()->getApplicationTypeAdmin();$model=new \Nextend\SmartSlider3\Application\Model\ModelSliders($context);
$id=$model->create(['title'=>'Autoplay policy fixture','type'=>'simple','width'=>1200,'height'=>600,'responsive-mode'=>'auto','responsiveLimitSlideWidth'=>1,'widget-arrow-enabled'=>1,'widgetarrow'=>'imageEmpty','autoplay'=>1,'autoplayStart'=>1,'autoplayDuration'=>1200,'autoplayLoop'=>1,'autoplayStopMouse'=>'enter','autoplayResumeMouse'=>'leave','autoplayStopClick'=>1,'autoplayResumeClick'=>1,'animation-duration'=>0]);
if(!$id)throw new RuntimeException('Autoplay slider creation failed');$slides=new \Nextend\SmartSlider3\Application\Model\ModelSlides($context);$uploads=wp_upload_dir();
for($i=0;$i<3;$i++){if(!file_exists($uploads['path'].'/scene-'.$i.'.png'))throw new RuntimeException('Seed the base slider first');$created=$slides->createQuickImage(['description'=>'Local autoplay fixture','media'=>$uploads['url'].'/scene-'.$i.'.png','title'=>'Autoplay scene '.($i+1),'alt'=>'Fixture artwork '.($i+1)],$id);if(!$created)throw new RuntimeException('Autoplay slide creation failed');}
$page=wp_insert_post(['ID'=>$existing?:0,'post_type'=>'page','post_status'=>'publish','post_title'=>'Autoplay policy check','post_name'=>'slider-autoplay-check','post_content'=>'[smartslider3 slider="'.$id.'"]']);if(is_wp_error($page)||!$page)throw new RuntimeException('Autoplay page creation failed');update_option('cloner_fixture_autoplay_page',$page);update_option('cloner_fixture_autoplay_ready',true);flush_rewrite_rules();echo json_encode(['url'=>get_permalink($page),'sliderId'=>$id])."\n";
